<div class="asignaturas-acciones"><button type="button" class="personas-accion" x-on:click="consultar(@js($m->cod_asi),$event.currentTarget)" :disabled="!!procesando" aria-label="Ver ficha y docentes de {{ $m->nom_asi }}" title="Ficha y docentes"><i class="ph-duotone ph-eye" aria-hidden="true"></i></button><button type="button" class="personas-accion" x-on:click="abrir('editar',@js($m->cod_asi),$event.currentTarget)" :disabled="!!procesando" aria-label="Editar {{ $m->nom_asi }} con motivo" title="Editar con motivo"><i class="ph-duotone ph-pencil-simple" aria-hidden="true"></i></button><button type="button" class="personas-accion" x-on:click="abrir(@js($m->est_asi==='ACTIVO'?'retirar':'recuperar'),@js($m->cod_asi),$event.currentTarget)" :disabled="!!procesando" aria-label="{{ $m->est_asi==='ACTIVO'?'Retirar':'Recuperar' }} {{ $m->nom_asi }} con motivo" title="{{ $m->est_asi==='ACTIVO'?'Retirar':'Recuperar' }} con motivo"><i class="ph-duotone {{ $m->est_asi==='ACTIVO'?'ph-archive':'ph-arrow-counter-clockwise' }}" aria-hidden="true"></i></button></div>
